/* GTE operations func_800AD138 needs that include/gte_inline.h does not yet
   carry.  Every COP2 word is read off the target's own listing, not out of
   psyq/include/inline_c.h, whose operation macros spell themselves as a bare
   `.word` and assemble to the wrong bytes through modern gas:
     nclip  0x4B400006   avsz3 0x4B58002D   ncds 0x4AE80413
   `gte_ncds_b()` is the NO-nop form (inline_c.h:863); the listing has
   mtc2/addiu/sb where gte_ncds()'s two `nop`s would be.  These belong in
   include/gte_inline.h once the function lands. */
#define gte_ldrgb(r0) __asm__ volatile("lwc2 $6, 0(%0)" ::"r"(r0))

#define gte_lddp(r0) __asm__ volatile("mtc2 %0, $8" ::"r"(r0))

#define gte_nclip() __asm__ volatile("nop\n\tnop\n\tc2 0x1400006")

#define gte_avsz3() __asm__ volatile("nop\n\tnop\n\tc2 0x158002D")

#define gte_ncds_b() __asm__ volatile("c2 0xE80413")

#define gte_stopz(r0) __asm__ volatile("swc2 $24, 0(%0)" ::"r"(r0) : "memory")

#define gte_stdp(r0) __asm__ volatile("swc2 $8, 0(%0)" ::"r"(r0) : "memory")

#define gte_stotz(r0) __asm__ volatile("swc2 $7, 0(%0)" ::"r"(r0) : "memory")

#define gte_strgb(r0) __asm__ volatile("swc2 $22, 0(%0)" ::"r"(r0) : "memory")

#define gte_stszotz(r0) __asm__ volatile("mfc2 $12, $19\n\tnop\n\t" \
                                         "sra $12, $12, 2\n\tsw $12, 0(%0)" ::"r"(r0) : "$12", "memory")

#define gte_stsxy3_ft4(r0) __asm__ volatile("swc2 $12, 8(%0)\n\t"  \
                                            "swc2 $13, 16(%0)\n\t" \
                                            "swc2 $14, 24(%0)" ::"r"(r0) : "memory")

/* WHICH NUMBER THIS PARK CARRIES, AND WHY -- read before the table below.
 *
 * Three results on the corner-block copy, and they are not interchangeable:
 *
 *   46 differing   the first park (scratch/n2_func.c), superseded
 *    9 differing   THIS BODY -- the best spelling that could be real source
 *    6 differing   the same body with `__asm__("" : "=r"(cc) : "0"(b));` in
 *                  place of the `cc = b;` / second-read pair
 *
 * The 6 is a DIAGNOSTIC, not a candidate, and the park deliberately does not
 * carry it.  A zero-length asm tying one local to another's value is not a
 * thing the original programmer wrote; it is a way of asking the compiler for
 * a copy insn directly.  What it proves is worth keeping, though: with the
 * copy forced into existence, the residue drops to six words that are a pure
 * PERMUTATION -- two loads swapped and four insns rotated by one, every word
 * present with the correct opcode, register and immediate, zero renames.  So
 * the remaining difference is sched1 position inside one basic block and
 * nothing else.  The device is also innocent of that residue: the legal
 * 9-differing spelling has a real `move $v0,$a0` at exactly the target's
 * index 229 and still schedules the increment early.
 *
 * TWO PASSES EACH BLOCK THE COPY, and between them they close the question
 * the first park left open as a named gap -- "which spelling reaches cse's
 * copy".  From a pointer-local spelling, none does:
 *
 *   cse cannot keep the read.  `invalidate_memory` (cse.c:1728) drops an
 *   entry when `cse_rtx_addr_varies_p`, and that returns 0 only for a MEM
 *   whose base register's quantity has a KNOWN CONSTANT (cse.c:2487-2508).
 *   With `p = (SP *)0x1F800000` assigned once at the function top, the
 *   constant equivalence is not live in the loop-body block, so the entry
 *   goes on any memory write.  Note what this exonerates: the stores are
 *   harmless.  `note_mem_written` (cse.c:7607-7622) only sets `writes->all`
 *   for a store that is neither in-struct nor a PLUS address, and the corner
 *   stores are `(mem:HI (plus reg const))`, so only `nonscalar` is set.  THE
 *   OBSTACLE IS THE POINTER'S CONSTANT EQUIVALENCE, NOT THE STORES -- which
 *   names the single condition that would unblock it.
 *
 *   combine cannot leave a source-level copy.  The only guard in
 *   `can_combine_p` that stops `(set cc b)` folding into
 *   `(set cc (plus cc 0x40))` requires `b` to be SET between the two insns.
 *   Measured: `b = b;`, `b += 0;`, `b |= 0;` and `__asm__ volatile("")` all
 *   fold away first (431 words / 203 differing).  The only legal intervening
 *   set that survives to combine is a genuine second memory read, which is
 *   what this body does.
 *
 * THE 9 IS A FLAT PLATEAU, and that is the useful negative.  All 143 legal
 * statement orders of the corner block measure the same, as do: the corner
 * stores written NOT in-struct, the vz stores written that way, three
 * spellings of each halfword read, the vz chain as four separate statements
 * and in three positions, and a "memory" clobber on gte_ldv3.  The
 * MEM_IN_STRUCT_P axis is now exhausted on the SCRATCHPAD side of this block
 * as well as the POLY_FT4 side -- which, with the sibling park
 * docs/near-misses/func_800AC4C4.c, closes that axis for the whole family.
 *
 * WHAT THIS CANDIDATE STILL HOLDS FIXED, highest-yield first:
 *
 *   1. The scratchpad as ONE pointer local assigned once at the function top.
 *      cse.c:2487 says the copy becomes reachable the moment the base
 *      register's quantity is a known constant IN THE LOOP-BODY BLOCK -- i.e.
 *      if the pointer were re-materialised inside the tile block.  Every
 *      spelling of that costs one `lui` (+1 word), which is why it was not
 *      taken, and NOBODY HAS MEASURED whether the word comes back elsewhere.
 *      This is the top remaining lead.
 *   2. No basic-block boundary inside the corner block.  combine's LOG_LINKs
 *      do not cross one, so a copy and its increment in different blocks
 *      would survive legally.  Untried: no free boundary was found.
 *   3. unk_20C as two u8 fields with the store cast (worth 85 words).
 *   4. The three edge loops as `for (i = 3; i >= 0; i--)` over
 *      `p->unk_1C[i]`.
 *   5. `volatile u16` for the depth-cue read.
 *
 * LIKELY TRANSFERABLE TO THE SIBLING PARK.  func_800AC4C4's cluster A is the
 * same residue -- it loads `m->unk_14`/`unk_16` once and copies, and its park
 * records reachable states of "cse succeeds + copy propagated away" (794
 * words) or "cse fails + a real reload" (797), never both.  That is this
 * function's 431-vs-432 dichotomy exactly, and the two citations above
 * explain why no legal spelling reaches it there either.
 *
 * A CORRECTION TO THE FIRST PARK'S RELOCATION NOTE.  The twelve R_MIPS_LO16
 * records this C does not reproduce are a SPLAT ARTIFACT, not evidence about
 * the original source.  splat annotates an `addiu rX,rY,imm` after a `lui` as
 * an address pair and invents a symbol, and
 * splat/town.bin_undefined_syms_auto.txt then defines
 * `D_1F8000C0 = 0x1F8000C0;` -- so `%lo(D_1F8000C0)` IS 0xC0 and each of the
 * twelve words resolves to exactly the word this C emits, verified
 * individually.  They do not affect `make build/town.bin`.  The first park's
 * conclusion that a permuter can never score 0 against target.o still holds,
 * because object-level relocation records cannot match; but it should not be
 * read as the original source having used symbols.
 */

